from models import Transaction, TxType
import storage

class BudgetTracker:
    def __init__(self, path=storage.DEFAULT_PATH):
        self.path = path
        data = storage.load(path)
        self.next_id = data.get("next_id", 1)
        self.savings_goal = float(data.get("savings_goal", 0.0))
        self.transactions = [Transaction.from_dict(d) for d in data.get("transactions", [])]

    def _persist(self):
        storage.save({"next_id": self.next_id, "savings_goal": self.savings_goal,
                      "transactions": [t.to_dict() for t in self.transactions]}, self.path)

    def add(self, ttype, category, amount, note=""):
        if amount <= 0:
            raise ValueError("Amount must be positive.")
        t = Transaction(TxType(ttype), category.strip() or "Uncategorized", round(amount, 2), note, id=self.next_id)
        self.next_id += 1
        self.transactions.append(t)
        self._persist()
        return t

    def delete(self, tx_id):
        before = len(self.transactions)
        self.transactions = [t for t in self.transactions if t.id != tx_id]
        if len(self.transactions) == before:
            raise ValueError(f"No transaction with id {tx_id}.")
        self._persist()

    def set_savings_goal(self, goal):
        if goal < 0:
            raise ValueError("Goal cannot be negative.")
        self.savings_goal = round(goal, 2)
        self._persist()

    def totals(self):
        income = sum(t.amount for t in self.transactions if t.type is TxType.INCOME)
        expenses = sum(t.amount for t in self.transactions if t.type is TxType.EXPENSE)
        return income, expenses, income - expenses

    def expenses_by_category(self):
        cats = {}
        for t in self.transactions:
            if t.type is TxType.EXPENSE:
                cats[t.category] = cats.get(t.category, 0.0) + t.amount
        return dict(sorted(cats.items(), key=lambda kv: -kv[1]))

    def report(self):
        income, expenses, savings = self.totals()
        lines = ["=== Budget Summary ===",
                 f"Total income : ${income:,.2f}",
                 f"Total expense: ${expenses:,.2f}",
                 f"Net savings  : ${savings:,.2f}"]
        if self.savings_goal > 0:
            pct = min(100.0, savings / self.savings_goal * 100)
            bar = "#" * int(pct // 5)
            lines.append(f"Savings goal : ${self.savings_goal:,.2f} ({pct:.1f}% reached) [{bar:<20}]")
        lines.append("--- Expenses by category ---")
        cats = self.expenses_by_category()
        if cats:
            for c, amt in cats.items():
                lines.append(f"  {c:<20} ${amt:,.2f}")
        else:
            lines.append("  (no expenses recorded)")
        return "\n".join(lines)

    def list_transactions(self):
        if not self.transactions:
            return "No transactions recorded."
        lines = [f"{'ID':>4} {'Date':<12} {'Type':<8} {'Category':<18} {'Amount':>12}  Note"]
        for t in sorted(self.transactions, key=lambda t: (t.date, t.id)):
            lines.append(f"{t.id:>4} {t.date:<12} {t.type.value:<8} {t.category:<18} ${t.amount:>10,.2f}  {t.note}")
        return "\n".join(lines)
