from tracker import BudgetTracker

DATA_FILE = "budget_data.json"

MENU = """
=== Budget Tracker ===
1) Add expense
2) Add income
3) Set category budget
4) Set savings goal
5) List entries
6) Report
7) Delete entry
0) Quit
"""


def fmt(x):
    return f"${x:,.2f}"


def ask_amount(msg):
    while True:
        try:
            v = float(input(msg).strip())
            if v >= 0:
                return round(v, 2)
        except ValueError:
            pass
        print("Please enter a valid non-negative number.")


def ask_date():
    d = input("Date (YYYY-MM-DD, blank=today): ").strip()
    return d or None


def add_expense(t):
    cat = input("Category (e.g. food, rent): ").strip() or "misc"
    amt = ask_amount("Amount: ")
    note = input("Note (optional): ").strip()
    e = t.add_expense(cat, amt, note, ask_date())
    print(f"Added expense #{e.id}: {e.category} {fmt(e.amount)}")


def add_income(t):
    src = input("Source (e.g. salary): ").strip() or "income"
    amt = ask_amount("Amount: ")
    note = input("Note (optional): ").strip()
    e = t.add_income(src, amt, note, ask_date())
    print(f"Added income #{e.id}: {e.category} {fmt(e.amount)}")


def set_budget(t):
    cat = input("Category: ").strip()
    if not cat:
        print("Cancelled.")
        return
    limit = ask_amount("Monthly budget limit: ")
    t.set_budget(cat, limit)
    print(f"Budget for '{cat}' set to {fmt(limit)}")


def set_goal(t):
    g = ask_amount("Savings goal: ")
    t.set_savings_goal(g)
    print(f"Savings goal set to {fmt(g)}")


def list_entries(t):
    kind = input("Show (e)xpenses or (i)ncome? ").strip().lower()
    entries = t.list_entries("expense" if kind.startswith("e") else "income")
    if not entries:
        print("Nothing recorded yet.")
        return
    for e in entries:
        print(f"#{e['id']} {e['date']} {e['category']:<15} {fmt(e['amount']):>12}  {e['note']}")


def delete_entry(t):
    kind = input("Delete (e)xpense or (i)ncome? ").strip().lower()
    kind = "expense" if kind.startswith("e") else "income"
    try:
        eid = int(input("Entry id: ").strip())
    except ValueError:
        print("Invalid id.")
        return
    if t.delete(kind, eid):
        print(f"Deleted entry #{eid}.")
    else:
        print("Entry not found.")


def report(t):
    inc, exp, net = t.totals()
    print("\n=== Summary ===")
    print(f"Income:   {fmt(inc)}")
    print(f"Expenses: {fmt(exp)}")
    print(f"Net:      {fmt(net)}")
    saved, goal, pct = t.savings_progress()
    if goal > 0:
        bar = "#" * int(pct // 5)
        print(f"Savings:  {fmt(saved)} of {fmt(goal)} goal ({pct:.1f}%) [{bar}]")
    print("\n=== Categories ===")
    rows = t.category_report()
    if not rows:
        print("No expenses recorded.")
    for cat, spent, limit, left in rows:
        line = f"{cat:<15} spent {fmt(spent):>12}"
        if limit is not None:
            status = "OK" if left >= 0 else "OVER"
            line += f" | budget {fmt(limit):>12} | left {fmt(left):>12} [{status}]"
        print(line)


def main():
    t = BudgetTracker(DATA_FILE)
    actions = {"1": add_expense, "2": add_income, "3": set_budget,
               "4": set_goal, "5": list_entries, "6": report, "7": delete_entry}
    print("Welcome to your Budget Tracker! Data is saved to", DATA_FILE)
    while True:
        print(MENU)
        choice = input("Choose an option: ").strip()
        if choice == "0":
            print("Goodbye!")
            break
        action = actions.get(choice)
        if action:
            action(t)
        else:
            print("Invalid option.")


if __name__ == "__main__":
    main()
