import storage
from models import Entry, today


class BudgetTracker:
    def __init__(self, path="budget_data.json"):
        self.path = path
        self.data = storage.load(path)

    def persist(self):
        storage.save(self.path, self.data)

    def _next_id(self):
        nid = self.data["next_id"]
        self.data["next_id"] = nid + 1
        return nid

    def add_expense(self, category, amount, note="", date=None):
        e = Entry(self._next_id(), date or today(), category, note, round(float(amount), 2))
        self.data["expenses"].append(e.to_dict())
        self.persist()
        return e

    def add_income(self, source, amount, note="", date=None):
        e = Entry(self._next_id(), date or today(), source, note, round(float(amount), 2))
        self.data["incomes"].append(e.to_dict())
        self.persist()
        return e

    def set_budget(self, category, limit):
        self.data["budgets"][category] = round(float(limit), 2)
        self.persist()

    def set_savings_goal(self, goal):
        self.data["savings_goal"] = round(float(goal), 2)
        self.persist()

    def delete(self, kind, entry_id):
        key = "expenses" if kind == "expense" else "incomes"
        before = len(self.data[key])
        self.data[key] = [e for e in self.data[key] if e["id"] != entry_id]
        removed = len(self.data[key]) < before
        if removed:
            self.persist()
        return removed

    def totals(self):
        inc = round(sum(e["amount"] for e in self.data["incomes"]), 2)
        exp = round(sum(e["amount"] for e in self.data["expenses"]), 2)
        return inc, exp, round(inc - exp, 2)

    def savings_progress(self):
        _, _, net = self.totals()
        goal = self.data["savings_goal"]
        pct = (net / goal * 100.0) if goal > 0 else 0.0
        return net, goal, min(max(pct, 0.0), 100.0)

    def category_report(self):
        spent = {}
        for e in self.data["expenses"]:
            spent[e["category"]] = round(spent.get(e["category"], 0.0) + e["amount"], 2)
        rows = []
        for cat, limit in self.data["budgets"].items():
            s = spent.get(cat, 0.0)
            rows.append((cat, s, limit, round(limit - s, 2)))
        for cat in sorted(k for k in spent if k not in self.data["budgets"]):
            rows.append((cat, spent[cat], None, None))
        return rows

    def list_entries(self, kind):
        return self.data["expenses" if kind == "expense" else "incomes"]
